using System;using System.IO;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class GuidanceUITests {
  string dir;GameRuntime game;static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-goals-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(GameRuntime.SavePathOverride,new UnitySaveCodec());var s=store.Load(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()).State;s.Story=StoryState.Migrated();s.Retention.aiName="AURA";store.Save(s);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  [UnityTest]public IEnumerator RealPlannerToggleRestartsOriginalInterval(){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Meta.resets=1;n.Meta.axioms[Array.FindIndex(MetaBalance.Axioms,d=>d.Id=="C02")]=1;n.Meta.axioms[Array.FindIndex(MetaBalance.Axioms,d=>d.Id=="C03")]=1;n.Meta.analysisSeconds=n.Meta.craftSeconds=1.5;n.Story.enabled=false;n.Story.open=null;return n;});game.Show("prestige");game.PrestigeView.SetLayer(true);game.PrestigeView.OpenNode("C02");yield return null;Click("AutoAnalysis");Assert.That(game.State.Meta.analysisAuto,Is.True);Assert.That(game.State.Meta.analysisSeconds,Is.Zero);game.PrestigeView.OpenNode("C03");yield return null;Click("AutoCraft");Assert.That(game.State.Meta.craftAuto,Is.True);Assert.That(game.State.Meta.craftSeconds,Is.Zero);var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.State.Meta.craftAuto,Is.True);}
  [UnityTest]public IEnumerator ExactAgentBudgetClearAndUneditedFieldsUseRealSavedControls(){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Workshop.nodes=new[]{"I06","F05","H01"};n.Prestige.known=(string[])n.Workshop.nodes.Clone();n.Prestige.creditReserve=ScientificNumber.Parse("1234567890123456789012345").ToData();n.Story.enabled=false;n.Story.open=null;return n;});game.Show("prestige");game.PrestigeView.OpenNode("I06");yield return null;var field=GameObject.Find("MinimumINT").GetComponent<InputField>();field.text="1e500";field.onEndEdit.Invoke(field.text);Assert.That(game.State.Prestige.Minimum.CompareTo(ScientificNumber.Parse("1e500")),Is.Zero);var read=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.State.Prestige.Minimum.CompareTo(ScientificNumber.Parse("1e500")),Is.Zero);game.PrestigeView.OpenNode("F05");yield return null;field=GameObject.Find("DirectorBudget").GetComponent<InputField>();field.text="100";field.onEndEdit.Invoke(field.text);Assert.That(game.State.Prestige.directorBudgetSet,Is.True);field=GameObject.Find("DirectorBudget").GetComponent<InputField>();field.text="";field.onEndEdit.Invoke(field.text);Assert.That(game.State.Prestige.directorBudgetSet,Is.False);game.PrestigeView.OpenNode("H01");yield return null;var reserve=ScientificNumber.FromData(game.State.Prestige.creditReserve);field=GameObject.Find("SharedCreditReserve").GetComponent<InputField>();field.onEndEdit.Invoke(field.text);Assert.That(ScientificNumber.FromData(game.State.Prestige.creditReserve).CompareTo(reserve),Is.Zero,"Unedited display must not round away saved exact terms");}
  [UnityTest]public IEnumerator ProductionAndPreviousSessionExportsUseActualRuntimeAndKeepUncleanOriginal(){Click("ResearchTab");yield return null;Click("ProductionAccess");yield return null;yield return null;Assert.That(GameObject.Find("ProductionFacts").GetComponent<Text>().text,Does.Contain("Parallelrechner / Hardware-Verbund"));WorkshopTests.Capture(390,844,"/tmp/unity-production-390.png");var crash=game.Crash.Ledger.Current;UnityEngine.Object.Destroy(game.gameObject);yield return null;crash.cleanExit=false;crash.hasEnd=false;string path=GameRuntime.SavePathOverride+".diagnostics.json";string original=JsonUtility.ToJson(crash);File.WriteAllText(path,original);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.Writable,Is.True);Assert.That(game.Crash.PreviousUnexpected,Is.True);Assert.That(game.Crash.Previous.failures[game.Crash.Previous.failures.Length-1].kind,Is.EqualTo("unexpected-session-end"));game.Show("storage");yield return null;Click("ExportPreviousCrash");Assert.That(Directory.GetFiles(Path.Combine(dir,"Exports"),"crash-*.json").Length,Is.EqualTo(1));bool found=false;foreach(string file in Directory.GetFiles(dir,"*.session-original-*"))found|=File.ReadAllText(file)==original;Assert.That(found,Is.True);}
  [UnityTest]public IEnumerator ExplicitCampaignResetCanCancelAndPreservesCompletePreviousCampaign(){game.Act(s=>Game.Buy(s,"calculator"));Assert.That(game.State.Hardware[0],Is.EqualTo(1));game.Show("settings");yield return null;Click("RequestCampaignReset");Assert.That(game.State.Hardware[0],Is.EqualTo(1));Click("CancelCampaignReset");Assert.That(game.State.Hardware[0],Is.EqualTo(1));Click("RequestCampaignReset");Click("ConfirmCampaignReset");yield return null;Assert.That(game.State.Hardware,Is.All.Zero);Assert.That(game.State.Retention.aiName,Is.Empty);string original=Directory.GetFiles(Path.Combine(dir,"CampaignOriginals"),"previous-campaign-*.json")[0];Assert.That(game.Storage.Inspect(original).State.Hardware[0],Is.EqualTo(1));Assert.That(game.Storage.Inspect(original).State.Retention.aiName,Is.EqualTo("AURA"));}
  [UnityTest]public IEnumerator ActualPauseButtonCancelsPendingAutomationBeforeReload(){game.Act(s=>{var n=s.Copy();n.Prestige.agent=true;n.Meta.axiomAuto=true;return n;});game.Show("prestige");yield return null;Click("PauseAutomaticResets");Assert.That(game.State.Prestige.agent,Is.False);Assert.That(game.State.Meta.axiomAuto,Is.False);var read=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(read.State.Prestige.agent,Is.False);Assert.That(read.State.Meta.axiomAuto,Is.False);}
  [UnityTest]public IEnumerator RealPinNavigateReloadClearAndDiagnosticExport(){Click("ResearchTab");yield return null;Click("GoalsAccess");yield return null;var credits=game.State.Credits;Click("PinGoal-hardware-sbc");Assert.That(game.State.Guidance.hasPinned,Is.True);Assert.That(game.State.Guidance.pinned.id,Is.EqualTo("sbc"));Assert.That(game.State.Credits.CompareTo(credits),Is.Zero);Click("GoToCurrentGoal");yield return null;yield return null;Assert.That(GameObject.Find("hardware-sbc"),Is.Not.Null);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Guidance.pinned.id,Is.EqualTo("sbc"));Click("ResearchTab");yield return null;Click("GoalsAccess");yield return null;Click("ClearPinnedGoal");Assert.That(game.State.Guidance.hasPinned,Is.False);foreach(string language in SettingsCatalog.Languages){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("goals");yield return null;yield return null;foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-goals-"+language+"-"+width+".png");}game.Show("storage");yield return null;Click("ExportLocalDiagnostics");string[] files=Directory.GetFiles(Path.Combine(dir,"Exports"),"diagnostics-*.json");Assert.That(files.Length,Is.EqualTo(1));string raw=File.ReadAllText(files[0]);Assert.That(raw,Does.Contain("file-runtime"));Assert.That(raw,Does.Contain("lastSuccessfulSave"));Assert.That(game.Diagnostics.hasSave,Is.True);Assert.That(game.Diagnostics.lastSaveBytes,Is.GreaterThan(0));Assert.That(game.Diagnostics.ticks,Is.GreaterThan(0));}
  [UnityTest]public IEnumerator DamagedMainHasReachableExplicitRecoveryAndKeepsOriginal(){game.Show("storage");yield return null;Click("ExportUnitySave");string source=Directory.GetFiles(Path.Combine(dir,"Exports"),"unity-*.json")[0];File.WriteAllText(game.SavePath,"damaged original from recovery UI test");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.Writable,Is.False);Click("ResearchTab");yield return null;Click("StorageAccess");yield return null;Click("ExportOriginalFile");string opaque=Directory.GetFiles(Path.Combine(dir,"Exports"),"original-file-*.json")[0];Assert.That(File.ReadAllText(opaque),Is.EqualTo("damaged original from recovery UI test"));GameObject.Find("RecoveryPathInput").GetComponent<InputField>().text=source;Click("InspectRecoveryPath");Assert.That(game.Writable,Is.False,"Preview cannot overwrite the original");Click("ConfirmRecovery");yield return null;Assert.That(game.Writable,Is.True);Assert.That(Directory.GetFiles(dir,"*-original-*").Length,Is.GreaterThan(0));bool preserved=false;foreach(string file in Directory.GetFiles(dir,"*-original-*"))preserved|=File.ReadAllText(file)=="damaged original from recovery UI test";Assert.That(preserved,Is.True);Assert.That(game.Diagnostics.recoveries,Is.GreaterThan(0));}
 }
}
